use std::path::PathBuf;

use clap::{Parser, Subcommand};

/// Toggl command line app.
#[derive(Parser, Debug)]
#[command(name = "toggl")]
#[command(about = "Toggl command line app.", long_about = None)]
#[command(subcommand_required = true, arg_required_else_help = true)]
#[command(after_long_help = "\
Examples:
  toggl entry start -d \"Working on feature\"
  toggl entry stop
  toggl entry running
  toggl entry list")]
pub struct Cli {
    #[command(subcommand)]
    pub cmd: Command,

    #[arg(short = 'C', help = "Change directory before running the command")]
    pub directory: Option<PathBuf>,

    #[arg(long, help = "Use custom proxy")]
    pub proxy: Option<String>,
}

#[derive(Subcommand, Debug)]
pub enum Command {
    /// Authenticate with Toggl API or check auth status.
    Auth {
        #[command(subcommand)]
        action: Option<AuthAction>,
        #[arg(help = "API token for authentication")]
        api_token: Option<String>,
        #[arg(long, help = "Toggl service type: 'official' or 'opentoggl'")]
        api_type: Option<String>,
        #[arg(long, help = "API URL for self-hosted Toggl (required for opentoggl)")]
        api_url: Option<String>,
    },
    /// Clear stored credentials.
    Logout,
    /// Show current user profile information.
    #[command(after_long_help = "\
Examples:
  toggl me                        Show your profile info
  toggl me --json                 Show your profile as JSON")]
    Me {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Manage time entries.
    #[command(after_long_help = "\
Examples:
  toggl entry start -d \"Working on feature\"
  toggl entry running
  toggl entry stop
  toggl entry list --since yesterday")]
    Entry {
        #[command(subcommand)]
        action: EntryAction,
    },
    /// Manage projects.
    Project {
        #[command(subcommand)]
        action: ProjectAction,
    },
    /// Manage tags.
    Tag {
        #[command(subcommand)]
        action: TagAction,
    },
    /// Manage clients.
    Client {
        #[command(subcommand)]
        action: ClientAction,
    },
    /// Manage tasks.
    Task {
        #[command(subcommand)]
        action: TaskAction,
    },
    /// Manage workspaces.
    Workspace {
        #[command(subcommand)]
        action: WorkspaceAction,
    },
    /// Inspect organizations.
    Org {
        #[command(subcommand)]
        action: OrganizationAction,
    },
    /// Show current user preferences.
    Preferences {
        #[command(subcommand)]
        action: PreferencesAction,
    },
    /// Generate reports (summary, detailed, weekly)
    #[command(after_long_help = "\
Examples:
  toggl report summary
  toggl report summary --since today --until today
  toggl report detailed --since yesterday --until today
  toggl report weekly --since 2026-03-17 --until 2026-03-23
  toggl report detailed --json -n 100")]
    Report {
        #[command(subcommand)]
        action: ReportAction,
    },
    /// Manage configuration.
    Config {
        #[arg(
            short,
            long,
            help = "Edit the configuration file in $EDITOR, defaults to vim"
        )]
        edit: bool,
        #[arg(short, long, help = "Delete the configuration file")]
        delete: bool,
        #[arg(short, long, help = "Print the path of the configuration file")]
        path: bool,
        #[command(subcommand)]
        cmd: Option<ConfigAction>,
    },
}

#[derive(Subcommand, Debug)]
pub enum EntryAction {
    /// Show the currently running time entry.
    #[command(
        name = "running",
        alias = "current",
        after_long_help = "\
Examples:
  toggl entry running             Show the running entry
  toggl entry running --json      Show the running entry as JSON

Note: JSON output includes a \"running\": true field for active entries."
    )]
    Current {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// List time entries.
    #[command(after_long_help = "\
Examples:
  toggl entry list
  toggl entry list --since today
  toggl entry list --since yesterday --until today
  toggl entry list --since 2024-01-01 --number 5
  toggl entry list --json | jq '.[].description'")]
    List {
        #[arg(short, long, help = "Maximum number of items to print")]
        number: Option<usize>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
        #[arg(
            long,
            help = "Filter time entries starting on or after this date/time (now, today, yesterday, this_week, last_week, YYYY-MM-DD, or full datetime)"
        )]
        since: Option<String>,
        #[arg(
            long,
            help = "Filter time entries before this date/time (now, today, yesterday, this_week, last_week, YYYY-MM-DD, or full datetime)"
        )]
        until: Option<String>,
    },
    /// Stop the currently running time entry.
    #[command(after_long_help = "\
Examples:
  toggl entry stop                Stop the running entry
  toggl entry stop --json         Stop and output as JSON")]
    Stop {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Start a new time entry (runs immediately with no prompt when called without arguments).
    #[command(after_long_help = "\
Examples:
  toggl entry start -d \"Writing docs\" -p MyProject
  toggl entry start -d \"Meeting\" --start 09:00 --end 10:00
  toggl entry start --json")]
    Start {
        #[arg(short, long, help = "Description of the time entry")]
        description: Option<String>,
        #[arg(
            short,
            long,
            help = "Exact name of the project you want the time entry to be associated with"
        )]
        project: Option<String>,
        #[arg(
            long,
            help = "Exact name of the task you want the time entry to be associated with"
        )]
        task: Option<String>,
        #[arg(short, long, help = "Tag name (repeatable), e.g. -t tag1 -t tag2")]
        tags: Option<Vec<String>>,
        #[arg(short, long, help = "Mark the time entry as billable")]
        billable: bool,
        #[arg(
            long,
            help = "Start date/time. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        start: Option<String>,
        #[arg(
            long,
            help = "End date/time. Requires --start. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        end: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Continue a previous time entry.
    #[command(
        name = "continue",
        alias = "resume",
        after_long_help = "\
Examples:
  toggl entry continue              Continue most recent entry
  toggl entry continue --id 12345   Continue a specific entry by ID
            help = "End date (YYYY-MM-DD, or: today, yesterday, now, this_week, last_week). Default: today"
        )]
        until: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
        #[arg(short, long, help = "Maximum number of entries per page")]
        number: Option<i64>,
        #[arg(
            long,
            help = "Order by: date, user, duration, description (default: date)"
        )]
        order_by: Option<String>,
        #[arg(long, help = "Order direction: ASC or DESC")]
        order_dir: Option<String>,
    },
    /// Weekly report with daily breakdown
    #[command(after_long_help = "\
Examples:
  toggl report weekly
  toggl report weekly --since today --until today
  toggl report weekly --since 2026-03-17 --until 2026-03-23 --json")]
    Weekly {
        #[arg(
            long,
            help = "Start date (YYYY-MM-DD, or: today, yesterday, now, this_week, last_week). Default: this_week"
        )]
        since: Option<String>,
        #[arg(
            long,
            help = "End date (YYYY-MM-DD, or: today, yesterday, now, this_week, last_week). Default: today"
        )]
        until: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
}

impl Command {
    /// Returns true if the parsed command includes a `--json` output flag.
    /// Used by the top-level error handler to format errors as JSON when appropriate.
    pub fn has_json_flag(&self) -> bool {
        match self {
            Command::Me { json } => *json,
            Command::Entry { action } => match action {
                EntryAction::Current { json }
                | EntryAction::List { json, .. }
                | EntryAction::Stop { json }
                | EntryAction::Start { json, .. }
                | EntryAction::Resume { json, .. }
                | EntryAction::Show { json, .. }
                | EntryAction::Update { json, .. }
                | EntryAction::Delete { json, .. }
                | EntryAction::Search { json, .. } => *json,
                EntryAction::BulkEdit { .. } => false,
            },
            Command::Project { action } => match action {
                ProjectAction::List { json, .. } => *json,
                _ => false,
            },
            Command::Tag { action } => match action {
                TagAction::List { json } => *json,
                _ => false,
            },
            Command::Client { action } => match action {
                ClientAction::List { json, .. } => *json,
                _ => false,
            },
            Command::Task { action } => match action {
                TaskAction::List { json, .. } => *json,
                _ => false,
            },
    }
}

fn setup_working_directory(directory: Option<std::path::PathBuf>) -> ResultWithDefaultError<()> {
    if let Some(dir) = directory {
        if !dir.exists() {
            return Err(Box::new(error::ArgumentError::DirectoryNotFound(dir)));
        }
        if !dir.is_dir() {
            return Err(Box::new(error::ArgumentError::NotADirectory(dir)));
        }
        std::env::set_current_dir(dir).expect("Couldn't set current directory");
    }
    Ok(())
}

async fn execute_entry_command(
    action: EntryAction,
    proxy: Option<String>,
    picker: Box<dyn picker::ItemPicker>,
) -> ResultWithDefaultError<()> {
    // Validate required arguments BEFORE creating the API client to avoid
    // unnecessary keychain/storage access for validation failures.
    match &action {
        EntryAction::Show { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'show' requires an entry ID or --current flag. Run `toggl entry list` or `toggl entry running` to find one.".to_string(),
            )));
        }
        EntryAction::Update { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'edit' requires an entry ID or --current flag. Example: toggl entry edit --current -d \"New description\"".to_string(),
            )));
        }
        EntryAction::Update {
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            ..
        } if description.is_none()
            && billable.is_none()
            && project.is_none()
            && task.is_none()
            && tags.is_none()
            && start.is_none()
            && end.is_none() =>
        {
            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
            )));
        }
        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
            )));
        }
        EntryAction::BulkEdit { json: None, .. } => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'bulk-edit' requires --json flag with JSON payload".to_string(),
            )));
        }
        _ => {}
    }

    let api_client = get_api_client(proxy.clone())?;

    match action {
        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
        EntryAction::List {
            number,
            json,
            since,
            until,
        } => ListCommand::execute(api_client, number, json, since, until, None).await,
        EntryAction::Stop { json } => {
            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
            Ok(())
        }
        EntryAction::Start {
            billable,
            description,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            StartCommand::execute(
                api_client,
                picker,
                description,
                project,
                task,
                tags,
                billable,
                false,
                start,
                end,
                json,
            )
            .await
        }
        EntryAction::Resume { id, json } => {
            ContinueCommand::execute(api_client, None, id, json).await
        }
        EntryAction::Show { id, current, json } => {
            if current {
                // Get the current running entry and show it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => ShowCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                ShowCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Update {
            id,
            current,
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            if current {
                // Check if there's a running entry before attempting edit
                match api_client.get_current_time_entry_minimal().await? {
                    Some(_) => {
                        // There's a running entry, let EditCommand handle it with id=None
                        EditCommand::execute(
                            api_client,
                            None,
                            description,
                            billable,
                            project,
                            task,
                            tags,
                            start,
                            end,
                            json,
                        )
                        .await
                    }
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                EditCommand::execute(
                    api_client,
                    id,
                    description,
                    billable,
                    project,
                    task,
                    tags,
                    start,
                    end,
                    json,
                )
                .await
            }
        }
        EntryAction::Delete { id, current, json } => {
            if current {
                // Get the current running entry and delete it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => DeleteCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                DeleteCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Search {
            query,
            project,
            no_project,
            tags,
            no_tag,
            since,
            until,
            number,
            order_by,
            order_dir,
            json,
        } => {
            commands::search::execute(
                api_client, query, project, no_project, tags, no_tag, since, until, number,
                order_by, order_dir, json,
            )
            .await
        }
        EntryAction::BulkEdit { ids, json } => {
            // json is guaranteed Some due to validation above
            BulkEditTimeEntriesCommand::execute(api_client, ids.clone(), json.clone().unwrap())
                .await
        }
    }
}

